:root {
  --bg-void: #06080c;
  --bg-deep: #0a0e16;
  --bg-surface: #101622;
  --bg-panel: rgba(13, 19, 29, 0.88);
  --bg-panel-hover: rgba(18, 26, 40, 0.95);
  --gold-primary: #d4af37;
  --gold-bright: #f3cf58;
  --gold-dim: rgba(212, 175, 55, 0.18);
  --gold-glow: rgba(212, 175, 55, 0.45);
  --radar-green: #00ff66;
  --radar-dim: rgba(0, 255, 102, 0.15);
  --radar-glow: rgba(0, 255, 102, 0.4);
  --hostile-red: #ff2a3b;
  --hostile-dim: rgba(255, 42, 59, 0.2);
  --hostile-glow: rgba(255, 42, 59, 0.5);
  --ew-cyan: #00e5ff;
  --ew-dim: rgba(0, 229, 255, 0.18);
  --ew-glow: rgba(0, 229, 255, 0.45);
  --border-subtle: rgba(255, 255, 255, 0.1);
  --border-tactical: rgba(212, 175, 55, 0.35);
  --border-active: rgba(0, 255, 102, 0.45);
  --text-primary: #f0f4f9;
  --text-secondary: #90a0b6;
  --text-muted: #536275;
  --text-gold: #e2be4b;
  --font-mono: 'JetBrains Mono', 'SF Mono', 'Menlo', 'Consolas', 'Courier New', monospace;
  --font-sans: 'Inter', -apple-system, 'Segoe UI', 'Helvetica Neue', system-ui, sans-serif;
  --font-display: 'Space Grotesk', -apple-system, 'Segoe UI', system-ui, sans-serif;
}
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
html, body, #root {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background-color: var(--bg-void);
  font-family: var(--font-sans);
  color: var(--text-primary);
  -webkit-font-smoothing: antialiased;
  user-select: none;
}
::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}
::-webkit-scrollbar-track {
  background: rgba(10, 14, 22, 0.6);
}
::-webkit-scrollbar-thumb {
  background: var(--gold-dim);
  border-radius: 2px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--gold-primary);
}
.scanlines {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 9999;
  background: linear-gradient( rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.18) 50% ), linear-gradient( 90deg, rgba(255, 0, 0, 0.02), rgba(0, 255, 0, 0.01), rgba(0, 0, 255, 0.02) );
  background-size: 100% 3px, 6px 100%;
  opacity: 0.5;
}
.vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 9998;
  box-shadow: inset 0 0 80px rgba(0, 0, 0, 0.75), inset 0 0 30px rgba(10, 14, 22, 0.85);
}
.tactical-panel {
  background: var(--bg-panel);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--border-subtle);
  border-radius: 6px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
  position: relative;
  overflow: hidden;
}
.tactical-panel::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--gold-dim), transparent);
}
.tactical-corner-tl {
  position: relative;
}
.tactical-corner-tl::after {
  content: '';
  position: absolute;
  top: -1px;
  left: -1px;
  width: 8px;
  height: 8px;
  border-top: 2px solid var(--gold-primary);
  border-left: 2px solid var(--gold-primary);
  pointer-events: none;
}
.mono-hud {
  font-family: var(--font-mono);
  font-feature-settings: "tnum";
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}
.btn-tactical {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding: 8px 14px;
  border-radius: 4px;
  border: 1px solid var(--border-tactical);
  background: rgba(212, 175, 55, 0.08);
  color: var(--gold-bright);
  cursor: pointer;
  transition: all 0.15s ease-in-out;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}
.btn-tactical:hover {
  background: rgba(212, 175, 55, 0.22);
  border-color: var(--gold-primary);
  box-shadow: 0 0 12px var(--gold-glow);
  transform: translateY(-1px);
}
.btn-tactical:active {
  transform: translateY(1px);
}
.btn-hostile {
  border-color: rgba(255, 42, 59, 0.45);
  background: rgba(255, 42, 59, 0.12);
  color: #ff6675;
}
.btn-hostile:hover {
  background: rgba(255, 42, 59, 0.28);
  border-color: var(--hostile-red);
  box-shadow: 0 0 12px var(--hostile-glow);
}
.btn-ew {
  border-color: rgba(0, 229, 255, 0.45);
  background: rgba(0, 229, 255, 0.12);
  color: #55eeff;
}
.btn-ew:hover {
  background: rgba(0, 229, 255, 0.28);
  border-color: var(--ew-cyan);
  box-shadow: 0 0 12px var(--ew-glow);
}
.badge-gold {
  background: var(--gold-dim);
  border: 1px solid var(--border-tactical);
  color: var(--gold-bright);
  padding: 2px 7px;
  border-radius: 3px;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 600;
}
.badge-hostile {
  background: var(--hostile-dim);
  border: 1px solid rgba(255, 42, 59, 0.45);
  color: #ff7582;
  padding: 2px 7px;
  border-radius: 3px;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 600;
  animation: pulse-red 2s infinite ease-in-out;
}
.badge-radar {
  background: var(--radar-dim);
  border: 1px solid rgba(0, 255, 102, 0.45);
  color: var(--radar-green);
  padding: 2px 7px;
  border-radius: 3px;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 600;
}
@keyframes pulse-red {
  0%, 100% {
    box-shadow: 0 0 0 rgba(255, 42, 59, 0);
  }
  50% {
    box-shadow: 0 0 10px rgba(255, 42, 59, 0.4);
  }
}
@keyframes pulse-gold {
  0%, 100% {
    opacity: 0.8;
  }
  50% {
    opacity: 1;
    filter: drop-shadow(0 0 6px var(--gold-glow));
  }
}
